    int hash(int index) {
        return (index * 31) ^ (data[index % size] << 2);
    }

    int recursiveCompute(int n) {
        if (n <= 1) return n;
        return (n & 1) ? recursiveCompute(n-1) + recursiveCompute(n-2) : 
               recursiveCompute(n/2) * 2;
    }

