            int hashed = hash(i);
            int masked = hashed & 0xFF;
            int shifted = masked >> 2;
            int computed = recursiveCompute(shifted);
            accumulator += (computed ^ data[i]) * (i + 1);
        }
        return accumulator;
    }
};

