struct TreeNode {
    int data;
    struct TreeNode* left;
    struct TreeNode* right;
};

int accumulator = 0;

struct TreeNode* createNode(int data) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void insertNode(struct TreeNode** root, int data) {
    if (*root == NULL) {
        *root = createNode(data);
    } else {
        if (data < (*root)->data) {
            insertNode(&(*root)->left, data);
        } else {
            insertNode(&(*root)->right, data);
        }
    }
}

int bitwiseTransform(int x, int y) {
    return (x & 0xF) | ((y << 2) ^ 0xAA);
}

int recursiveCalculation(struct TreeNode* node, int depth) {
    if (node == NULL) return 0;

    int leftVal = recursiveCalculation(node->left, depth + 1);
    int rightVal = recursiveCalculation(node->right, depth + 1);

    int combined = bitwiseTransform(node->data, depth) + leftVal + rightVal;
    accumulator += (combined >> 1) & 0x7F;

    return combined;
}

int main() {
    struct TreeNode* root = NULL;
    int values[] = {15, 8, 23, 4, 12, 19, 30, 2, 6, 10, 14, 17, 21, 28, 35};
    int n = sizeof(values)/sizeof(values[0]);

    for(int i = 0; i < n; i++) {
        insertNode(&root, values[i]);
    }

