class DataProcessor {
private:
    std::vector<std::vector<int>> matrix;
    std::string key;

public:
    DataProcessor(std::vector<std::vector<int>> m, std::string k) : matrix(m), key(k) {}

    int customHash() {
        int hash = 0;
        for (char c : key) {
            hash = (hash << 5) - hash + static_cast<int>(c);
            hash &= 0xFFFFFFFF; // Ensure 32-bit
        }
        return hash;
    }

    int process() {
        int result = customHash();

        // Matrix transformation
        for (size_t i = 0; i < matrix.size(); ++i) {
            for (size_t j = 0; j < matrix[i].size(); ++j) {
                if ((i + j) % 2 == 0) {
                    matrix[i][j] = static_cast<int>(std::pow(matrix[i][j], 2));
                } else {
                    matrix[i][j] = static_cast<int>(std::sqrt(std::abs(matrix[i][j])));
                }
            }
        }

        // Aggregate calculation
        for (const auto& row : matrix) {
            int rowSum = 0;
            for (int val : row) {
                rowSum += val;
            }
            result ^= (rowSum << 2);
        }

        // Bitwise manipulation with recursive component
        int finalAdjustment = recursiveBitShift(result, 3);
        result = (result >> 4) | (finalAdjustment << 8);

        return result & 0xFFFF; // Return lower 16 bits
    }

private:
    int recursiveBitShift(int value, int depth) {
        if (depth <= 0) return value;
        int shifted = (value << 1) ^ (value >> 1);
        return recursiveBitShift(shifted, depth - 1);
    }
};

int main() {
    std::vector<std::vector<int>> data = {{3, -4, 5}, {6, -7, 8}, {9, -2, 1}};
    std::string secret = "CODE";
    DataProcessor processor(data, secret);
    int finalValue = processor.process();
    std::cout << finalValue << std::endl;
    return 0;
}

