    int process() {
        int result = 0;
        for (auto& pair : data_map) {
            int key = pair.first;
            std::vector<int>& vals = pair.second;

            for (size_t i = 0; i < vals.size(); ++i) {
                if (i % 2 == 0) {
                    result += (vals[i] ^ key) & 0xF;  // XOR with key, then mask lower 4 bits
                } else {
                    result += static_cast<int>(std::pow(vals[i], 1.5)) % (key + 1);
                }
            }
        }

        // Apply bit shift operations based on internal state
        if (internal_state > 10) {
            result = (result << 2) | (result >> 3);
        } else {
            result = (result >> 1) ^ (result << 2);
        }

        return result;
    }

    void updateState(int value) {
        internal_state += value;
    }
};

int recursiveFunction(int n, DataProcessor& processor) {
    if (n <= 1) {
        return processor.process();
    }

    // Modify processor state based on n
    processor.updateState(n * 2);

    // Add data to processor
    std::vector<int> vec;
    for (int i = 1; i <= n; ++i) {
        vec.push_back(i * n);
    }
    processor.addData(n, vec);

    return recursiveFunction(n - 1, processor) + n;
}

