int computeChecksum(Node* root, int depth) {
    if (root == NULL) return 0;

    int leftChecksum = computeChecksum(root->left, depth + 1);
    int rightChecksum = computeChecksum(root->right, depth + 1);

    int nodeValue = root->value;
    int maskedValue = nodeValue & ((1 << (depth + 1)) - 1);
    int transformedValue = (maskedValue * 3) + (depth ^ 5);

    return (leftChecksum ^ rightChecksum) + transformedValue;
}

