double recursive_calc(int n, std::map<int, double>& memo) {
    if (memo.find(n) != memo.end()) return memo[n];
    if (n <= 1) return memo[n] = 1.0;
    return memo[n] = std::sqrt(n * recursive_calc(n-1, memo) + recursive_calc(n-2, memo));
}

