class ComplexCalculator {
private:
    std::map<int, long long> fibMemo;

    long long fibonacci(int n) {
        if (n <= 1) return n;
        if (fibMemo.find(n) != fibMemo.end()) return fibMemo[n];
        return fibMemo[n] = fibonacci(n-1) + fibonacci(n-2);
    }

    int rotateLeft(int value, int shift, int bits) {
        shift %= bits;
        return ((value << shift) | (value >> (bits - shift))) & ((1 << bits) - 1);
    }

public:
    struct DataPoint {
        int x, y;
        double weight;
    };

    struct ComplexData {
        DataPoint points[3];
        int size;
        long long hash;
    };

    long long compute() {
        ComplexData data;
        data.size = 3;

        // Initialize data points
        data.points[0] = {5, 12, 1.5};
        data.points[1] = {8, 15, 2.0};
        data.points[2] = {7, 24, 3.2};

        // Compute hash based on points
        data.hash = 0;
        for(int i = 0; i < data.size; i++) {
            long long component = (data.points[i].x * data.points[i].y) ^ 
                                 (static_cast<long long>(data.points[i].weight * 100));
            data.hash ^= (component << (i * 8));
        }

        // Perform complex calculation sequence
        long long step1 = fibonacci(15) % 1000;
        double step2 = std::log(step1) * std::sin(data.points[0].x * 0.1) * std::cos(data.points[1].y * 0.05);
        int step3 = rotateLeft(static_cast<int>(data.hash & 0xFFFF), 7, 16);
        long long step4 = static_cast<long long>(std::floor(step2 * 1000)) ^ step3;

        // Final computation with nested operations
        long long result = 0;
        for(int i = 1; i <= 4; i++) {
            long long term = (step4 + fibonacci(i*3)) % 10000;
            result += (term * term) ^ (step1 >> (i-1));
        }

        return result;
    }
};

int main() {
    ComplexCalculator calc;
    long long result = calc.compute();
    std::cout << result << std::endl;
    return 0;
}

