public class ComplexCalculation {
    public static void main(String[] args) {
        int[][] matrix = {{2, 3, 3}, {4, 5, 6}, {7, 8, 9}};
        String encoded = "10#15#20";
        List<Integer> numbers = new ArrayList<>();

        // Parse encoded string
        String[] parts = encoded.split("#");
        for (String part : parts) {
            numbers.add(Integer.parseInt(part) >> 1); // Right shift by 1 (divide by 2)
        }

        // Calculate matrix diagonal product
        int diagonalProduct = 1;
        for (int i = 0; i < matrix.length; i++) {
            diagonalProduct *= matrix[i][i];
        }

        // Process numbers with a complex function
        int sum = 0;
        for (int num : numbers) {
            sum += computeValue(num, 3);
        }

        // Final calculation combining all components
        int result = (diagonalProduct & 0xFF) + (sum ^ 0xF0) - getTotalFromMatrix(matrix);

        System.out.println(result);
    }

    public static int computeValue(int base, int exp) {
        if (exp <= 1) return base << exp; // Left shift (multiply by 2^exp)
        return base * computeValue(base, exp - 1);
    }

    public static int getTotalFromMatrix(int[][] matrix) {
        int total = 0;
        for (int[] row : matrix) {
            for (int val : row) {
                total += val * (val % 3 == 0 ? 2 : 1);
            }
        }
        return total >> 2; // Right shift by 2 (divide by 4)
    }
}

