public class ComplexComputation {
    public static int recursiveFunction(int n, int[] memo) {
        if (n <= 1) return n;
        if (memo[n] != 0) return memo[n];
        memo[n] = recursiveFunction(n-1, memo) + recursiveFunction(n-2, memo);
        return memo[n];
    }

