        String binaryStr = Integer.toBinaryString(intermediateResult);
        int bitCount = 0;
        for (char c : binaryStr.toCharArray()) {
            if (c == '1') bitCount++;
        }

        int[] finalArray = new int[bitCount];
        for (int i = 0; i < bitCount; i++) {
            finalArray[i] = (intermediateResult >> i) & 1;
        }

        int result = 0;
        for (int i = 0; i < finalArray.length; i++) {
            result += finalArray[i] * Math.pow(2, i) * fibValue;
        }

        System.out.println(result);
    }
}

