}

int computeDepth(struct TreeNode* root) {
    if (root == NULL) return 0;
    int leftDepth = computeDepth(root->left);
    int rightDepth = computeDepth(root->right);
    return (leftDepth > rightDepth ? leftDepth : rightDepth) + 1;
}

void insertNode(struct TreeNode** root, int val) {
    if (*root == NULL) {
        *root = createNode(val);
    } else {
        if (val < (*root)->value) {
            insertNode(&(*root)->left, val);
        } else {
            insertNode(&(*root)->right, val);
        }
    }
}

int traverseAndSum(struct TreeNode* root, int level) {
    if (root == NULL) return 0;
    int sum = (root->value << level) ^ (level * 3);
    sum += traverseAndSum(root->left, level + 1);
    sum += traverseAndSum(root->right, level + 1);
    return sum;
}

