class Matrix3D {
private:
    std::vector<std::vector<std::vector<int>>> data;
    int dimX, dimY, dimZ;

public:
    Matrix3D(int x, int y, int z) : dimX(x), dimY(y), dimZ(z) {
        data.resize(dimX, std::vector<std::vector<int>>(dimY, std::vector<int>(dimZ, 0)));
    }

    void set(int x, int y, int z, int value) {
        data[x][y][z] = value;
    }

    int get(int x, int y, int z) const {
        return data[x][y][z];
    }

    int sum() const {
        int total = 0;
        for (const auto& plane : data)
            for (const auto& row : plane)
                for (int val : row)
                    total += val;
        return total;
    }

    void transform() {
        for (int i = 0; i < dimX; ++i)
            for (int j = 0; j < dimY; ++j)
                for (int k = 0; k < dimZ; ++k)
                    data[i][j][k] = (data[i][j][k] << 1) ^ (i + j + k);
    }
};

