int compute_value(int x, int y) {
    return (x << 2) ^ (y >> 1) + (int)sqrt(x * y);
}

Node* create_node(int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->value = val;
    n->left = NULL;
    n->right = NULL;
    return n;
}

void insert_node(Node* root, int val) {
    if (val < root->value) {
        if (root->left == NULL) {
            root->left = create_node(val);
        } else {
            insert_node(root->left, val);
        }
    } else {
        if (root->right == NULL) {
            root->right = create_node(val);
        } else {
            insert_node(root->right, val);
        }
    }
}

int traverse_and_modify(Node* node, int level) {
    if (node == NULL) return 0;
    int modifier = compute_value(node->value, level);
    node->value = node->value ^ modifier;
    int left_sum = traverse_and_modify(node->left, level + 1);
    int right_sum = traverse_and_modify(node->right, level + 1);
    return node->value + left_sum + right_sum;
}

