int compute(Polygon* poly, int index) {
    if (index >= poly->count) return 0;
    Point p = poly->points[index];
    int distance = (int)sqrt(p.x * p.x + p.y * p.y);
    return (distance ^ index) + compute(poly, index + 1);
}

