            String binaryHash = Integer.toBinaryString(hash);

            // Count the number of 1s in binary representation
            int onesCount = 0;
            for (char c : binaryHash.toCharArray()) {
                if (c == '1') onesCount++;
            }

            // Perform complex calculation combining log sum and bit count
            double calculation = Math.pow(logSum, 2) * Math.sqrt(onesCount) + 
                               Math.sin(onesCount) * Math.cos(logSum);

            // Add to result based on some conditions
            if (calculation > 10) {
                result += (int) Math.ceil(calculation);
            } else {
                result -= (int) Math.floor(Math.abs(calculation));
            }
