        String resultStr = String.valueOf(result);
        StringBuilder reversed = new StringBuilder(resultStr).reverse();
        int reversedInt = Integer.parseInt(reversed.toString());

        // XOR operation between result and its reverse
        result = result ^ reversedInt;

