        int result = 0;

        // Step 1: Apply mathematical transformation to each element
        for (auto& row : data) {
            for (auto& elem : row) {
                elem = static_cast<int>(std::pow(elem, 1.5)) + (elem & 0x3);
            }
        }

        // Step 2: Calculate diagonal sum with recursive adjustment
        for (size_t i = 0; i < data.size() && i < data[i].size(); ++i) {
            result += data[i][i] * recursiveSum(i+1);
        }

        // Step 3: Apply bit transformations between adjacent elements
        for (size_t i = 0; i < data.size(); ++i) {
            for (size_t j = 1; j < data[i].size(); ++j) {
                result += bitTransform(data[i][j-1], data[i][j]);
            }
        }

        // Step 4: Final mathematical adjustment
        result = static_cast<int>(std::sqrt(result)) ^ (result & 0xFF);

        return result;
    }
};

