        int result = 0;
        int n = matrix.size();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < matrix[i].size(); j++) {
                if (i == j) {
                    matrix[i][j] = static_cast<int>(std::pow(matrix[i][j], 2)) & 0xFF;
