        int xorResult = maxValue;
        for (int i = 1; i < values.size(); i++) {
            xorResult ^= values.get(i);
        }

        String concatStr = String.valueOf(maxValue) + String.valueOf(minValue) + String.valueOf(bitCount);
        int concatNum = Integer.parseInt(concatStr);

        int result = (int)(sqrtMax * logProduct) + (xorResult << 2) - concatNum + (product % 7);
    }
