int recursive_calc(int **arr, int row, int col, int depth) {
    if (depth <= 0 || row >= SIZE || col >= SIZE) return 0;

    int val = arr[row][col];
    int addr_offset = (int)((char*)&arr[row][col] - (char*)arr);
    int combined = (val << 3) ^ (addr_offset & 0xFF);

    if (row == col) {
        return combined + recursive_calc(arr, row+1, col+1, depth-1);
    } else {
        return combined ^ recursive_calc(arr, row, col+1, depth-1) ^ recursive_calc(arr, row+1, col, depth-1);
    }
}

