int bitwiseSum(int a, int b) {
    while (b != 0) {
        int carry = a & b;
        a = a ^ b;
        b = carry << 1;
    }
    return a;
}

void insertNode(struct TreeNode** root, int val) {
    if (*root == NULL) {
        *root = createNode(val);
    } else {
        if (val < (*root)->value) {
            insertNode(&(*root)->left, val);
        } else {
            insertNode(&(*root)->right, val);
        }
    }
}

int traverseAndCalculate(struct TreeNode* root, int* accumulator) {
    if (root == NULL) return 0;

    int leftResult = traverseAndCalculate(root->left, accumulator);
    int rightResult = traverseAndCalculate(root->right, accumulator);

    int nodeValue = root->value;
    int combined = bitwiseSum(bitwiseSum(leftResult, rightResult), nodeValue);

    if (nodeValue % 3 == 0) {
        *accumulator = bitwiseSum(*accumulator, combined << 2);
    } else if (nodeValue % 3 == 1) {
        *accumulator = bitwiseSum(*accumulator, combined >> 1);
    } else {
        *accumulator = bitwiseSum(*accumulator, combined ^ 0xF0);
    }

    return combined;
}

