    int computeDiagonalSum() {
        int sum = 0;
        for (int i = 0; i < matrix.size(); ++i) {
            sum += matrix[i][i];
        }
        return sum;
    }

    void generateKey(int seed) {
        key = "";
        for (int i = 0; i < 5; ++i) {
            key += static_cast<char>((seed % 26) + 'A');
            seed = (seed * 17 + 11) % 1000;
        }
    }

    int getKeySum() {
        int sum = 0;
        for (char c : key) {
            sum += static_cast<int>(c - 'A' + 1);
        }
        return sum;
    }

    static int recursiveFunction(int n, int depth = 0) {
        if (depth > 3) return n;
        if (n <= 1) return 1;
        return recursiveFunction(n / 2, depth + 1) + recursiveFunction(n / 3, depth + 1);
    }
};

