struct Node {
    int value;
    struct Node* left;
    struct Node* right;
};

int result = 0;

struct Node* createNode(int val) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->value = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int complexCalc(int x, int y) {
    int temp = (x & 0xF) << 2;
    temp ^= (y >> 1);
    return temp + (x * y) % 7;
}

void transformTree(struct Node* root, int level) {
    if (root == NULL) return;

    int mask = (1 << (level % 4)) - 1;
    root->value = (root->value & mask) | ((root->value >> 4) & (~mask));

    if (level % 3 == 0) {
        root->value = complexCalc(root->value, level);
    }

    transformTree(root->left, level + 1);
    transformTree(root->right, level + 1);
}

int traverseAndSum(struct Node* root, int depth) {
    if (root == NULL) return 0;

    int sum = root->value;
    if (depth > 2) {
        sum += traverseAndSum(root->left, depth - 1) * 2;
        sum -= traverseAndSum(root->right, depth - 1) / 3;
    } else {
        sum += traverseAndSum(root->left, depth + 1);
        sum += traverseAndSum(root->right, depth + 1);
    }

    return sum;
}

int main() {
    struct Node* root = createNode(15);
    root->left = createNode(22);
    root->right = createNode(8);
    root->left->left = createNode(31);
    root->left->right = createNode(17);
    root->right->left = createNode(9);
    root->right->right = createNode(4);

    transformTree(root, 1);
    result = traverseAndSum(root, 3);

    return 0;
}

