double recursive_power(double base, int exp) {
    if (exp == 0) return 1;
    if (exp < 0) return 1.0 / recursive_power(base, -exp);
    double half = recursive_power(base, exp / 2);
    if (exp % 2 == 0) return half * half;
    else return half * half * base;
}

