};

struct Container {
    struct Node* head;
    int count;
};

int recursive_calc(int n, int* arr, int idx) {
    if (n <= 1) return n;
    if (arr[idx] != -1) return arr[idx];
    int result = (recursive_calc(n-1, arr, idx-1) ^ recursive_calc(n-2, arr, idx-2)) & 0xFF;
    arr[idx] = result;
    return result;
}

struct Node* create_node(int val) {
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    new_node->value = val;
    new_node->next = NULL;
    return new_node;
}

void insert_at_end(struct Container* cont, int val) {
    struct Node* new_node = create_node(val);
    if (cont->head == NULL) {
        cont->head = new_node;
    } else {
        struct Node* temp = cont->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    cont->count++;
}

int main() {
    struct Container container = {NULL, 0};
    int values[] = {12, 25, 37, 48, 56};
    int size = sizeof(values)/sizeof(values[0]);

    for (int i = 0; i < size; i++) {
        insert_at_end(&container, values[i]);
    }

    int memo[100];
    for (int i = 0; i < 100; i++) memo[i] = -1;

    struct Node* current = container.head;
    int xor_result = 0;
    int idx = 0;

    while (current != NULL) {
        int fib_val = recursive_calc(current->value % 10, memo, (current->value % 10));
        xor_result ^= (fib_val << (idx % 4));
        current = current->next;
        idx++;
    }

    double sqrt_val = sqrt(xor_result);
    int final_result = (int)(sqrt_val) & 0x7F;

    // Clean up memory
    current = container.head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }

    return final_result;
}

