class DataProcessor {
public:
    struct NestedData {
        int values[3];
        std::string binary_str;
        double factor;
    };

    static int process(NestedData& data) {
        // Step 1: Perform trigonometric calculation on values[0]
        int trig_result = static_cast<int>(std::sin(data.values[0]) * 1000);

        // Step 2: Apply logarithmic transformation to values[1]
        int log_result = static_cast<int>(std::log(data.values[1]) * 100);

        // Step 3: Bitwise XOR of values[2] with trig_result
        int xor_result = data.values[2] ^ trig_result;

        // Step 4: Left shift xor_result by the number of '1's in binary_str
        int count_ones = 0;
        for (char c : data.binary_str) {
            if (c == '1') count_ones++;
        }
        int shifted = xor_result << count_ones;

        // Step 5: Convert binary_str to integer with base conversion
        int binary_value = std::stoi(data.binary_str, nullptr, 2);

        // Step 6: Multiply factor with log_result and add to shifted value
        int final_adjustment = static_cast<int>(data.factor * log_result);

        // Final computation
        return (shifted + binary_value) ^ final_adjustment;
    }
};

