int traverse_and_modify(Node* root, int depth) {
    if (root == NULL) return 0;

    int left_sum = traverse_and_modify(root->left, depth + 1);
    int right_sum = traverse_and_modify(root->right, depth + 1);

    int original_value = root->value;
    root->value = complex_calculation(depth, original_value) & 0xFF;

    return root->value + left_sum + right_sum;
