public class ComplexComputation {
    public static int recursiveFunc(int n, Map<String, Integer> memo) {
        if (n <= 1) return n;
        String key = "fib_" + n;
        if (memo.containsKey(key)) return memo.get(key);
        int value = recursiveFunc(n - 1, memo) + recursiveFunc(n - 2, memo);
        memo.put(key, value);
        return value;
    }

    public static void main(String[] args) {
