int recursive_sum(struct Node* node, int depth) {
    if (node == NULL) return 0;
    int val = node->value;
    if (depth > 0) {
        val = val << depth;
    }
    return val + recursive_sum(node->next, depth - 1);
}

int complex_operation(struct Container* container) {
    int result = 0;
    struct Node* current = container->head;
    int index = 0;

    while (current != NULL) {
        int temp = current->value;
        if (index % 2 == 0) {
            temp = temp ^ (index << 2);
        } else {
            temp = temp | (index >> 1);
        }
        result += temp;
        current = current->next;
        index++;
    }

    result = result & 0xFF;
    result = result ^ recursive_sum(container->head, 3);
    return result;
}

