        std::string processed = processString(keyStr);
        int strValue = std::stoi(processed);

        // Bitwise operations
        int xorResult = (strValue ^ 15) & 63;

        // Mathematical operations
        double powerResult = std::pow(xorResult, 1.5);
        int finalValue = static_cast<int>(std::floor(powerResult));

        // Iterate through dataMap
