}

int treeSum(Node* root) {
    if (root == NULL) return 0;
    return root->value + treeSum(root->left) + treeSum(root->right);
}

void transformTree(Node* root, int level) {
    if (root == NULL) return;
    if (level % 2 == 0) {
        root->value = root->value << 2;
    } else {
        root->value = root->value >> 1;
    }
    transformTree(root->left, level + 1);
    transformTree(root->right, level + 1);
}

int bitwiseXORSum(Node* root) {
    if (root == NULL) return 0;
    int leftSum = bitwiseXORSum(root->left);
    int rightSum = bitwiseXORSum(root->right);
    int xorVal = leftSum ^ rightSum;
    return root->value ^ xorVal;
}

