class DataProcessor {
private:
    std::vector<std::vector<std::vector<int>>> data;
    int depth;

public:
    DataProcessor(int d) : depth(d) {
        data.resize(d, std::vector<std::vector<int>>(d, std::vector<int>(d, 0)));
        initializeData();
    }

    void initializeData() {
        for(int i = 0; i < depth; i++) {
            for(int j = 0; j < depth; j++) {
                for(int k = 0; k < depth; k++) {
                    data[i][j][k] = (i + 1) * (j + 2) * (k + 3) + (i ^ j ^ k);
                }
            }
        }
    }

    int transformValue(int val, int x, int y, int z) {
        int temp = val;
        temp = (temp << 2) + (x & y) - z;
        temp = static_cast<int>(std::pow(temp, 1.5)) % 1000;
        temp ^= (x | y | z);
        return temp;
    }

    int recursiveReduce(int x, int y, int z) {
        if(x >= depth || y >= depth || z >= depth || x < 0 || y < 0 || z < 0) return 0;

        int current = transformValue(data[x][y][z], x, y, z);
        int next1 = recursiveReduce(x+1, y, z);
        int next2 = recursiveReduce(x, y+1, z);
        int next3 = recursiveReduce(x, y, z+1);

        return (current ^ next1 ^ next2 ^ next3) % 997;
    }

    int process() {
        return recursiveReduce(0, 0, 0);
    }
};

