struct TreeNode {
    int value;
    struct TreeNode* left;
    struct TreeNode* right;
};

struct TreeNode* createNode(int val) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->value = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int computeChecksum(struct TreeNode* root, int depth) {
    if (root == NULL) return 0;

    int leftSum = computeChecksum(root->left, depth + 1);
    int rightSum = computeChecksum(root->right, depth + 1);

    int nodeValue = root->value;
    int maskedValue = nodeValue & ((1 << (depth + 1)) - 1);
    int transformedValue = (maskedValue * 3 + depth * 7) ^ (leftSum & rightSum);

    return transformedValue + leftSum + rightSum;
}

