int recursiveModify(Node* node, int depth) {
    if (node == NULL) return 0;
    int modifier = (int)(pow(-1, depth) * sqrt(abs(node->value)));
    node->value += modifier;
    int leftSum = recursiveModify(node->left, depth + 1);
    int rightSum = recursiveModify(node->right, depth + 1);
    return node->value + leftSum + rightSum;
}

