int recursive_sum(Node* node, int depth) {
    if (!node) return 0;
    int left_sum = recursive_sum(node->left, depth + 1);
    int right_sum = recursive_sum(node->right, depth + 1);
    int combined = bitwise_transform(node->value, depth) + left_sum + right_sum;
    if (depth > 1) {
