class DataProcessor {
private:
    std::vector<std::vector<int>> matrix;
    std::string key;

public:
    DataProcessor(std::vector<std::vector<int>> m, std::string k) : matrix(m), key(k) {}

    int customHash() {
        int hash = 0;
        for (char c : key) {
            hash = (hash << 5) ^ c;  // Left shift by 5 and XOR
        }
        return hash & 0xFF;  // Mask to 8 bits
    }

    void transformMatrix() {
        int rows = matrix.size();
        int cols = matrix[0].size();
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if ((i + j) % 2 == 0) {
                    matrix[i][j] = (matrix[i][j] << 2) + 1;  // Left shift by 2 and add 1
                } else {
                    matrix[i][j] = (matrix[i][j] >> 1) ^ 3;  // Right shift by 1 and XOR with 3
                }
            }
        }
    }

    int calculateDeterminant() {
        // For simplicity, assume 2x2 matrix
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
    }

    int recursiveSum(int n) {
        if (n <= 1) return n;
        return n + recursiveSum(n - 1);
    }
};

