    std::vector<std::vector<int>> data = {{4, 7}, {2, 5}};
    DataProcessor processor(data, "secret");

    int hashValue = processor.customHash();
    processor.transformMatrix();
    int determinant = processor.calculateDeterminant();
    int sum = processor.recursiveSum(10);

    int finalResult = (hashValue & determinant) | (sum % 256);
    std::cout << finalResult;
    return 0;
}

