void insert_node(struct TreeNode** root, int val) {
    if (*root == NULL) {
        *root = create_node(val);
    } else {
        if (val < (*root)->value) {
            insert_node(&(*root)->left, val);
        } else {
            insert_node(&(*root)->right, val);
        }
    }
}

int traverse_and_calculate(struct TreeNode* root, int depth) {
    if (root == NULL) return 0;

    int left_sum = traverse_and_calculate(root->left, depth + 1);
    int right_sum = traverse_and_calculate(root->right, depth + 1);

    int node_value = root->value;
    int calculated_value = (node_value << depth) ^ (left_sum & right_sum) ^ global_counter;
    global_counter += (node_value % 3) ? (node_value * depth) : (node_value / (depth + 1));

    return calculated_value + left_sum + right_sum;
}

