int computeMaskedSum(struct TreeNode* root, int depth) {
    if (root == NULL) return 0;
    int mask = (depth % 3 == 0) ? 0xF0 : (depth % 3 == 1) ? 0x0F : 0xFF;
    int maskedValue = root->value & mask;
    int leftSum = computeMaskedSum(root->left, depth + 1);
    int rightSum = computeMaskedSum(root->right, depth + 1);
    return maskedValue + leftSum + rightSum + (depth << 2);
}

void modifyTreeValues(struct TreeNode* root, int modifier) {
    if (root == NULL) return;
    root->value = (root->value ^ modifier) + (modifier >> 1);
    modifyTreeValues(root->left, modifier - 1);
    modifyTreeValues(root->right, modifier + 1);
}

