        data.resize(x, std::vector<std::vector<int>>(y, std::vector<int>(z, 0)));
    }

    void populate() {
        for(int i = 0; i < x; i++) {
            for(int j = 0; j < y; j++) {
                for(int k = 0; k < z; k++) {
                    data[i][j][k] = (i + 1) * (j + 1) * (k + 1);
                }
            }
        }
    }

    int sumLayer(int layer) {
        int sum = 0;
        for(int j = 0; j < y; j++) {
            for(int k = 0; k < z; k++) {
                sum += data[layer][j][k];
            }
        }
        return sum;
    }
};

int recursiveFunc(int n) {
    if (n <= 1) return n;
    return recursiveFunc(n - 1) + recursiveFunc(n - 2);
}

