typedef struct Node {
    int value;
    struct Node* left;
    struct Node* right;
} Node;

int compute_value(int x, int y) {
    return (x & y) ^ (x << 1) ^ (int)sqrt(abs(x * y));
}

Node* create_node(int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->value = val;
    n->left = NULL;
    n->right = NULL;
    return n;
}

void build_tree(Node* root, int depth) {
    if (depth <= 0) return;
    int left_val = compute_value(root->value, depth);
    int right_val = compute_value(root->value, depth + 1);
    root->left = create_node(left_val);
    root->right = create_node(right_val);
    build_tree(root->left, depth - 1);
    build_tree(root->right, depth - 1);
}

int traverse_and_modify(Node* root, int level) {
    if (!root) return 0;
    int modifier = (root->value | level) & ~(root->value >> 1);
    root->value ^= modifier;
    int left_sum = traverse_and_modify(root->left, level + 1);
    int right_sum = traverse_and_modify(root->right, level + 1);
    return root->value + left_sum + right_sum;
}

