    private static Map<String, Integer> cache = new HashMap<>();

    public static int compute(int x, int y) {
        String key = x + "," + y;
        if (cache.containsKey(key)) return cache.get(key);

        if (x <= 0 || y <= 0) return 1;
        if (x > 2 || y > 2) return compute(x-1, y-1);

        int value = matrix[x][y] ^ (compute(x-1, y) | compute(x, y-1));
        cache.put(key, value);
        return value;
    }

