                if (Character.isDigit(c)) {
                    sum += Character.getNumericValue(c);
                }
            }

            int x = (sum >> 1) & 3;
            int y = (sum >> 2) & 3;

            result += compute(x, y) * (i + 1);
        }

        System.out.println(result);
    }
}

