double complex_calc(int* arr, int size, int depth) {
    if (depth <= 0) return 0.0;
    double result = 0.0;
    for (int i = 0; i < size; i++) {
        if (arr[i] & 1) {  // if odd
            result += std::pow(arr[i], 1.0/depth);
        } else {
            result -= std::log(static_cast<double>(arr[i] + 1));
        }
    }
    int new_size = size / 2;
    if (new_size > 0) {
        int* new_arr = new int[new_size];
        for (int i = 0; i < new_size; i++) {
            new_arr[i] = arr[i*2] ^ arr[i*2 + 1];
        }
        result += complex_calc(new_arr, new_size, depth - 1);
        delete[] new_arr;
    }
    return result;
}

