double complex_operation(int* arr, int size, int depth) {
    if (depth <= 0 || size <= 0) return 0.0;

    double result = 0.0;
    int* temp = new int[size];
    memcpy(temp, arr, size * sizeof(int));

    for (int i = 0; i < size; ++i) {
        if (i % 2 == 0) {
            temp[i] = (temp[i] << 2) ^ (temp[i] >> 1);
        } else {
            temp[i] = (temp[i] & 0xF) | (temp[i] << 4);
        }

        if (temp[i] > 100) {
            result += sqrt(static_cast<double>(temp[i])) * log(static_cast<double>(temp[i] + 1));
        } else {
            result += pow(static_cast<double>(temp[i]), 1.5);
        }
    }

    if (depth > 1) {
        result += complex_operation(temp, size - 1, depth - 1);
    }

    delete[] temp;
    return result;
}

