};

struct TreeNode* createNode(int val) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->value = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int computeMaskedSum(struct TreeNode* root, int depth) {
    if (root == NULL) return 0;
    int mask = (1 << (depth % 5)) - 1;
    int leftSum = computeMaskedSum(root->left, depth + 1);
    int rightSum = computeMaskedSum(root->right, depth + 1);
    int currentValue = (root->value & mask) * depth;
    return leftSum + rightSum + currentValue;
}

