int hash_str(const char* str) {
    int hash = 0;
    while (*str) {
        hash = (hash << 5) - hash + *str++;
        hash &= 0x7FFFFFFF;
    }
    return hash;
}

struct Node* create_node(int data) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int compute_value(int x, int y) {
    return ((x & 0xF) << 4) | (y & 0xF);
}

void insert_node(struct Node* root, int data) {
    if (data < root->data) {
        if (root->left == NULL) {
            root->left = create_node(data);
        } else {
            insert_node(root->left, data);
        }
    } else {
        if (root->right == NULL) {
            root->right = create_node(data);
        } else {
            insert_node(root->right, data);
        }
    }
}

int traverse_and_sum(struct Node* root) {
    if (root == NULL) return 0;
    int sum = root->data;
    sum += traverse_and_sum(root->left);
    sum += traverse_and_sum(root->right);
    return sum;
}

int main() {
    char* strings[] = {"alpha", "beta", "gamma", "delta", "epsilon"};
    int hashes[5];
    for (int i = 0; i < 5; i++) {
        hashes[i] = hash_str(strings[i]) % 100;
    }

    int vals[5];
    for (int i = 0; i < 5; i++) {
        vals[i] = compute_value(hashes[i], i);
    }

    struct Node* root = create_node(vals[0]);
    for (int i = 1; i < 5; i++) {
        insert_node(root, vals[i]);
    }

    int final_sum = traverse_and_sum(root);
    printf("%d\n", final_sum);

    return 0;
}

