            if((i+j)%2 == 0){
                matrix[i][j] <<= 1;  // Left shift by 1 (equivalent to multiply by 2)
            } else {
                matrix[i][j] ^= 1;   // XOR with 1 (flips the last bit)
            }
        }
    }

    // Step 2: Perform calculation using updated matrix values
    int sum_diag = 0;
    for(int i=0; i<min(matrix.size(), matrix[0].size()); i++){
