typedef struct TreeNode TreeNode;

int result = 0;

int parseAndTransform(char* str) {
    int len = strlen(str);
    int sum = 0;
    for (int i = 0; i < len; i++) {
        if (str[i] >= '0' && str[i] <= '9') {
            sum += (str[i] - '0');
        }
    }
    return (sum << 2) ^ (sum >> 1);
}

TreeNode* createNode(int val) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->value = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int traverseAndCalculate(TreeNode* root) {
    if (root == NULL) return 0;
    int leftVal = traverseAndCalculate(root->left);
    int rightVal = traverseAndCalculate(root->right);
    int combined = (leftVal & rightVal) | (root->value ^ (leftVal + rightVal));
    return combined + (int)sqrt(abs(root->value));
}

void buildTree(TreeNode** root, char** strings, int index, int depth) {
    if (index >= 7 || depth > 3) return;

    int val = parseAndTransform(strings[index]);
    *root = createNode(val);

    if (depth < 3) {
        buildTree(&(*root)->left, strings, index * 2 + 1, depth + 1);
        buildTree(&(*root)->right, strings, index * 2 + 2, depth + 1);
    }
}

