import java.util.*;

public class ComplexCalculation {
    public static void main(String[] args) {
        int[][] matrix = {{2, 3, 5}, {7, 11, 13}, {17, 19, 23}};
        String expression = "((5*3)+2^(4-1))";
        List<Integer> primes = new ArrayList<>(Arrays.asList(2, 3, 5, 7, 11));

        int result = 0;

        // Step 1: Process matrix diagonal product
        for (int i = 0; i < matrix.length; i++) {
            result += matrix[i][i] * (i + 1);
        }

        // Step 2: Parse and evaluate expression
        expression = expression.replaceAll("\s+", "");
        int exprValue = evaluateExpression(expression);
        result ^= exprValue;

        // Step 3: Manipulate primes list
        Iterator<Integer> iterator = primes.iterator();
        while (iterator.hasNext()) {
            Integer prime = iterator.next();
            if (prime % 2 == 0) {
                result += prime << 2;
                iterator.remove();
            } else {
                result -= prime >> 1;
            }
        }

        // Step 4: Complex nested loop calculation
        int temp = 0;
        for (int i = 1; i <= 4; i++) {
            for (int j = i; j <= 4; j++) {
                temp += (int) Math.pow(i, j) % (j + 1);
            }
        }
        result |= temp;

        // Step 5: Final adjustment
        result = (result & 0xFF) + (result >> 8);

        System.out.println(result);
    }

    private static int evaluateExpression(String expr) {
        // Simplified expression evaluator for this problem
        // Assumes well-formed expressions with single digit numbers and basic operations
        expr = expr.replaceAll("[()]+", "");
        String[] parts = expr.split("\\+");
        int value1 = Integer.parseInt(parts[0].substring(0, 1)) * Integer.parseInt(parts[0].substring(2, 3));
        String[] parts2 = parts[1].split("\\^");
        int value2 = (int) Math.pow(Integer.parseInt(parts2[0].substring(0, 1)), Integer.parseInt(parts2[0].substring(2, 3)));
        return value1 + value2;
    }
}

