int cache[20];
int result = 0;

int fibonacci(int n) {
    if (n <= 1) return n;
    if (cache[n] != 0) return cache[n];
    cache[n] = fibonacci(n-1) + fibonacci(n-2);
    return cache[n];
}

int process_block(DataBlock* block, int index) {
    int sum = 0;
    for (int i = 0; i < 4; i++) {
        if ((i & 1) == 0) {
            sum += block->values[i] * index;
        } else {
            sum -= block->values[i] >> 1;
        }
    }
    return sum ^ (strlen(block->tag) << 2);
}

void complex_operation() {
    int intermediate[3];
    for (int i = 0; i < 3; i++) {
        intermediate[i] = process_block(&blocks[i], i+1);
    }

    int mask = 0xF0;
    int accum = 0;
    for (int j = 2; j >= 0; j--) {
        accum = (accum << 3) | ((intermediate[j] & mask) >> 4);
    }

    int fib_index = (accum & 0x1F) + 10;
    result = fibonacci(fib_index) + (accum >> 5);
}

