int global_counter = 0;

Node* create_node(int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->value = val;
    n->left = NULL;
    n->right = NULL;
    return n;
}

void insert_node(Node* root, int val) {
    if (val < root->value) {
        if (root->left == NULL) {
            root->left = create_node(val);
        } else {
            insert_node(root->left, val);
        }
    } else {
        if (root->right == NULL) {
            root->right = create_node(val);
        } else {
            insert_node(root->right, val);
        }
    }
}

int traverse_and_compute(Node* root) {
    if (root == NULL) return 0;
    int left_val = traverse_and_compute(root->left);
    int right_val = traverse_and_compute(root->right);
    int combined = (left_val ^ right_val) + root->value;
    global_counter += (combined & 0xF);
    return combined;
}

