class Tensor3D {
private:
    std::vector<std::vector<std::vector<int>>> data;
    int dim1, dim2, dim3;

public:
    Tensor3D(int d1, int d2, int d3) : dim1(d1), dim2(d2), dim3(d3) {
        data.resize(dim1, std::vector<std::vector<int>>(dim2, std::vector<int>(dim3, 0)));
    }

    void set(int i, int j, int k, int value) {
        if (i >= 0 && i < dim1 && j >= 0 && j < dim2 && k >= 0 && k < dim3) {
            data[i][j][k] = value;
        }
    }

    int get(int i, int j, int k) const {
        if (i >= 0 && i < dim1 && j >= 0 && j < dim2 && k >= 0 && k < dim3) {
            return data[i][j][k];
        }
        return 0;
    }

    int dimensions() const { return dim1 * dim2 * dim3; }

    int sum() const {
        int total = 0;
        for (const auto& plane : data)
            for (const auto& row : plane)
                for (const auto& elem : row)
                    total += elem;
