int traverse_and_modify(Node* root, int level) {
    if (!root) return 0;
    int modifier = (level % 2 == 0) ? 1 : -1;
    root->value = (root->value >> 1) & 0x7F;
    root->value *= modifier;
    return root->value + traverse_and_modify(root->left, level + 1) + traverse_and_modify(root->right, level + 1);
}

