        int accumulator = 0;

        // Step 1: Perform XOR operations on diagonal elements
        for (size_t i = 0; i < matrix.size() && i < matrix[i].size(); ++i) {
            accumulator ^= matrix[i][i];
        }

        // Step 2: Apply mathematical transformation
        accumulator = static_cast<int>(std::pow(accumulator, 2)) + 3 * accumulator - 7;

        // Step 3: Bitwise operations with key length
        int key_factor = static_cast<int>(key.length());
        accumulator = (accumulator << 2) | (key_factor & 0xF);

        // Step 4: Matrix border sum
        int border_sum = 0;
        if (!matrix.empty()) {
            size_t rows = matrix.size();
            size_t cols = matrix[0].size();

            // Top and bottom rows
            for (size_t j = 0; j < cols; ++j) {
                border_sum += matrix[0][j];
                if (rows > 1) border_sum += matrix[rows-1][j];
            }

            // Left and right columns (excluding corners already counted)
            for (size_t i = 1; i < rows-1; ++i) {
                border_sum += matrix[i][0];
                if (cols > 1) border_sum += matrix[i][cols-1];
            }
        }

        // Step 5: Final calculation
        int result = (accumulator & 0xFF) + (border_sum % 17) * 3 - static_cast<int>(std::sqrt(key_factor));
        return result;
    }
