        dataMap = new HashMap<>();
        dataMap.put("values", Arrays.asList(12, 45, 28, 67, 34));
    }

    public int complexCalculation() {
        int result = 0;

        // Step 1: Process matrix diagonals
        int primaryDiagonal = 0;
        int secondaryDiagonal = 0;
        for (int i = 0; i < matrix.length; i++) {
            primaryDiagonal += matrix[i][i];
            secondaryDiagonal += matrix[i][matrix.length - 1 - i];
        }

        // Step 2: Apply mathematical transformations
        int diagonalDiff = Math.abs(primaryDiagonal - secondaryDiagonal);
        result = (int) Math.pow(diagonalDiff, 2) + (diagonalDiff % 7);

        // Step 3: Incorporate map data with string operations
        String concatenated = dataMap.get("values").stream()
            .map(String::valueOf)
            .reduce("", String::concat);
        int stringSum = concatenated.chars().map(Character::getNumericValue).sum();

        // Step 4: Bitwise operations
        result = (result << 2) ^ (stringSum >> 1);

        // Step 5: Recursive factorial with conditional logic
        int factorialInput = (result % 10) + 5;
        long factorial = computeFactorial(factorialInput);

        // Step 6: Final calculation combining all components
        result = (int) ((result * 3) + Math.sqrt(factorial) - (primaryDiagonal & secondaryDiagonal));

        return result;
