class DataProcessor {
private:
    std::vector<std::vector<int>> matrix;
    std::string key;

public:
    DataProcessor(std::vector<std::vector<int>> m, std::string k) : matrix(m), key(k) {}

    int process() {
        int accumulator = 0;

        // Step 1: Perform bitwise operations on matrix elements
        for (size_t i = 0; i < matrix.size(); ++i) {
            for (size_t j = 0; j < matrix[i].size(); ++j) {
                if ((i & 1) == 0) {  // Even row
                    matrix[i][j] = matrix[i][j] ^ (key.length() << 2);
                } else {  // Odd row
                    matrix[i][j] = (matrix[i][j] | (key[j % key.length()] & 0x0F)) & 0xFF;
                }
            }
        }

        // Step 2: Mathematical transformations
        for (auto& row : matrix) {
            for (int& val : row) {
                if (val > 100) {
                    val = static_cast<int>(std::sqrt(val) * 10);
                } else if (val < 20) {
                    val = val * val + 2 * val + 1;
                } else {
                    val = (val << 1) + (val >> 1);
                }
            }
        }

        // Step 3: Aggregate calculations
        for (size_t i = 0; i < matrix.size(); ++i) {
            int row_sum = 0;
            for (size_t j = 0; j < matrix[i].size(); ++j) {
                row_sum += matrix[i][j] * (i + 1) * (j + 1);
            }
            accumulator ^= row_sum;
        }

        // Step 4: Final transformation using key
        int key_factor = 0;
        for (char c : key) {
            key_factor += (c - 'A' + 1) * (c - 'a' + 1);
        }

        return (accumulator + key_factor) % 1000;
    }
};

