    struct Node* right;
} Node;

Node* createNode(int val) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = val;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

void insertNode(Node* root, int val) {
    if (val < root->value) {
        if (root->left == NULL) {
            root->left = createNode(val);
        } else {
            insertNode(root->left, val);
        }
    } else {
        if (root->right == NULL) {
            root->right = createNode(val);
        } else {
            insertNode(root->right, val);
        }
    }
}

int xorByDepth(Node* node, int depth) {
    if (node == NULL) return 0;
    int xorVal = node->value ^ (0xF0 >> (depth % 4));
    node->value = xorVal;
    xorByDepth(node->left, depth + 1);
    xorByDepth(node->right, depth + 1);
    return xorVal;
}

long long weightedSum(Node* node, int depth) {
    if (node == NULL) return 0;
    long long weight = (long long)pow(2, depth);
    return (node->value * weight) + weightedSum(node->left, depth + 1) + weightedSum(node->right, depth + 1);
}

