class DataProcessor {
private:
    std::map<int, std::vector<int>> data_map;

public:
    DataProcessor() {
        // Initialize with complex nested data
        data_map[1] = {2, 4, 8, 16};
        data_map[2] = {3, 9, 27, 81};
        data_map[3] = {5, 25, 125, 625};
    }

    int process() {
        int result = 0;

        // Lambda for complex calculation
        auto complex_calc = [](int x, int y) -> int {
            return (x << 2) ^ (y >> 1) + static_cast<int>(std::sqrt(x * y));
        };

        // Process each entry in the map
        for (const auto& [key, vec] : data_map) {
            int local_sum = 0;

            // Apply transformations to vector elements
            std::vector<int> transformed;
            for (size_t i = 0; i < vec.size(); ++i) {
                int val = vec[i];
                if (i % 2 == 0) {
                    val = val | (key << i);
                } else {
                    val = val & ~(key >> (i-1));
                }
                transformed.push_back(val);
            }

            // Calculate local sum using complex_calc
            for (size_t i = 0; i < transformed.size() - 1; ++i) {
                local_sum += complex_calc(transformed[i], transformed[i+1]);
            }

            // Apply additional mathematical transformation
            local_sum = static_cast<int>(std::pow(local_sum, 1.0/3.0) * 100);

            // XOR with key for final local value
            result ^= (local_sum << key);
        }

        // Final adjustment using string manipulation
        std::string result_str = std::to_string(result);
        std::reverse(result_str.begin(), result_str.end());

        // Sum of digits in reversed string
        int digit_sum = 0;
        for (char c : result_str) {
            if (isdigit(c)) {
                digit_sum += (c - '0');
            }
        }

        return (result & 0xFF) + digit_sum;
    }
};

