int compute_hash(char* str) {
    int hash = 0;
    for (int i = 0; i < strlen(str); i++) {
        hash = (hash << 5) - hash + str[i];
        hash = hash & 0x7FFFFFFF;
    }
    return hash;
}

Node* create_node(int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->value = val;
    n->left = NULL;
    n->right = NULL;
    return n;
}

int traverse_and_modify(Node* root, int depth) {
    if (!root) return 0;
    int left_sum = traverse_and_modify(root->left, depth + 1);
    int right_sum = traverse_and_modify(root->right, depth + 1);
    int combined = left_sum ^ right_sum;
    root->value = (root->value * depth) + (combined & 0xFF);
    return root->value + left_sum + right_sum;
}

void build_tree(Node** root, char** strings, int n) {
    for (int i = 0; i < n; i++) {
        int hash = compute_hash(strings[i]);
        int val = (hash % 1000) + (int)floor(sqrt((double)i + 1));
        if (!*root) {
            *root = create_node(val);
        } else {
            Node* current = *root;
            while (1) {
                if (val < current->value) {
                    if (!current->left) {
                        current->left = create_node(val);
                        break;
                    }
                    current = current->left;
                } else {
                    if (!current->right) {
                        current->right = create_node(val);
                        break;
                    }
                    current = current->right;
                }
            }
        }
    }
}

