struct TreeNode {
    int value;
    struct TreeNode* left;
    struct TreeNode* right;
};

int result = 0;
int mask = 0xF0F0F0F0;

struct TreeNode* createNode(int val) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->value = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int complexCalculation(int a, int b) {
    int x = (a & 0xFF) << 8;
    int y = (b >> 4) & 0x0F;
    return (x | y) ^ ((a * b) & mask);
}

void traverseAndModify(struct TreeNode* node, int depth) {
    if (node == NULL) return;

    int addr = (int)(uintptr_t)node;
    int modifiedValue = complexCalculation(node->value, depth) ^ (addr & 0xFFFF);
    node->value = modifiedValue;

    if (depth % 2 == 0) {
        result += (node->value & 0xFF);
    } else {
        result -= (node->value >> 8) & 0xFF;
    }

    if (node->left != NULL && node->right != NULL) {
        int condition = (node->value & 0xF) == 0;
        if (condition) {
            traverseAndModify(node->left, depth + 1);
            traverseAndModify(node->right, depth + 1);
        } else {
            traverseAndModify(node->right, depth + 1);
            traverseAndModify(node->left, depth + 1);
        }
    } else if (node->left != NULL) {
        traverseAndModify(node->left, depth + 1);
    } else if (node->right != NULL) {
        traverseAndModify(node->right, depth + 1);
    }
}

