struct TreeNode {
    int value;
    struct TreeNode* left;
    struct TreeNode* right;
};

int computeValue(int x, int y) {
    return (x & y) ^ ((x << 1) + (y >> 1)) + (int)sqrt(abs(x - y));
}

struct TreeNode* createNode(int val) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->value = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void buildTree(struct TreeNode* root, int depth) {
    if (depth <= 0) return;
    int leftVal = computeValue(root->value, depth);
    int rightVal = computeValue(root->value, root->value ^ depth);
    root->left = createNode(leftVal);
    root->right = createNode(rightVal);
    buildTree(root->left, depth - 1);
    buildTree(root->right, depth - 1);
}

int traverseAndModify(struct TreeNode* node, int level) {
    if (!node) return 0;
    int modification = (node->value | level) & ~(node->value ^ level);
    node->value += modification;
    int leftSum = traverseAndModify(node->left, level + 1);
    int rightSum = traverseAndModify(node->right, level + 1);
    return node->value + leftSum + rightSum;
}

