int treeSum(Node* root) {
    if (root == NULL) return 0;
    return root->data + treeSum(root->left) + treeSum(root->right);
}

void modifyTree(Node* root, int* arr, int index) {
    if (root == NULL) return;
    root->data = root->data ^ arr[index];
    modifyTree(root->left, arr, (index + 1) % 5);
    modifyTree(root->right, arr, (index + 2) % 5);
}

