            int sum = values.stream().mapToInt(Integer::intValue).sum();
            total += (keyHash * sum) % 97;
        }
        return total;
    }

    public int recursiveCalc(int n) {
        if (n <= 1) return n;
        return (recursiveCalc(n - 1) + recursiveCalc(n - 2)) % 1000;
    }
