typedef struct Node {
    int value;
    struct Node* left;
    struct Node* right;
} Node;

int compute_value(int x, int y) {
    int result = 0;
    for (int i = 1; i <= x; i++) {
        result += (i * y) ^ (y >> 1);
    }
    return result & 0xFF;
}

Node* create_node(int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->value = val;
    n->left = NULL;
    n->right = NULL;
    return n;
}

void build_tree(Node* root, int depth, int x, int y) {
    if (depth <= 0) return;
    int left_val = compute_value(x, y) + depth;
    int right_val = compute_value(y, x) - depth;
    root->left = create_node(left_val);
    root->right = create_node(right_val);
    build_tree(root->left, depth-1, x-1, y+1);
    build_tree(root->right, depth-1, x+1, y-1);
}

int traverse_and_modify(Node* root, int level) {
    if (!root) return 0;
    int modification = (int)(pow(level, 1.5) * sin(level * 0.5));
    root->value = (root->value ^ modification) & 0xFF;
    int left_sum = traverse_and_modify(root->left, level + 1);
    int right_sum = traverse_and_modify(root->right, level + 1);
    return root->value + left_sum + right_sum;
}

int main() {
    int x = 7, y = 3;
    Node* root = create_node(compute_value(x, y));
    build_tree(root, 3, x, y);
    int total = traverse_and_modify(root, 1);
    printf("%d", (root->right->left->value * 3) % 100);
    return 0;
}

import math

def recursive_sum(data, depth=0):
    if depth > 3:
        return 0
    total = 0
    for item in data:
        if isinstance(item, list):
            total += recursive_sum(item, depth + 1)
        elif isinstance(item, dict):
            total += sum(recursive_sum([v], depth + 1) if isinstance(v, (list, dict)) else v for v in item.values())
        else:
            total += item
    return total

