double calculate(double x, int y) {
    return pow(x, 2) + sqrt(y) * 2;
}

int main() {
    std::vector<std::vector<int>> matrix = {{10, 20, 30}, {40, 50, 60}, {70, 80, 90}};
    std::string text = "ComplexEvaluation";

    int a = matrix[1][2];
    int b = text.length();

    double c = calculate(a, b);

    int d = static_cast<int>(c) & 0xFF;
    int e = (d << 2) ^ 0x55;

    double f = sin(e % 90) * cos(e % 45);

    std::vector<int> arr = {static_cast<int>(f * 1000), e, d, b, a};

    int g = 0;
    for (int i = 0; i < arr.size(); i++) {
        g += arr[i] * (i + 1);
    }

    int h = (g | 0x0F) & ~(0xF0);

    double result = sqrt(h) + log(static_cast<double>(h)) + tan(h % 10);

    return static_cast<int>(result);
}

import java.util.*;

public class ComplexCalculation {
    public static void main(String[] args) {
        int[][] matrix = {{2, 3, 5}, {7, 11, 13}, {17, 19, 23}};
        String[] words = {"hello", "world", "java", "programming"};

        int sum = 0;
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                if ((i & 1) == 0) {
                    sum += matrix[i][j] * (int)Math.pow(j + 1, 2);
                } else {
                    sum -= matrix[i][j] >> 1;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (String word : words) {
            sb.append(word.charAt(word.length() - 1));
        }

        int hash = sb.toString().hashCode();
        int xorResult = 0;
        for (int i = 0; i < words.length; i++) {
            xorResult ^= words[i].length();
        }

        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);
        int product = numbers.stream().reduce(1, (a, b) -> a * b);

        Map<String, Integer> map = new HashMap<>();
        map.put("sum", sum);
        map.put("hash", hash);
        map.put("xor", xorResult);
        map.put("product", product);

        int result = (map.get("sum") + map.get("hash")) ^ (map.get("xor") | map.get("product"));
        result = (result << 2) + (result >> 1);

        System.out.println(result);
    }
}

