int main() {
    Rectangle rect = {{2, 3}, {8, 7}, {10, 20, 30, 40}};

    // Step 1: Compute area using coordinates
    int width = rect.p2.x - rect.p1.x;
    int height = rect.p2.y - rect.p1.y;
    int area = width * height;

    // Step 2: Perform bitwise operations on array elements
    int xor_result = rect.values[0] ^ rect.values[1] ^ rect.values[2] ^ rect.values[3];

    // Step 3: Apply mathematical transformations
    double sqrt_area = sqrt((double)area);
    int transformed = (int)(sqrt_area * 10);

    // Step 4: Conditional assignment based on bitwise outcome
    int conditional_value;
    if ((xor_result & 0xF) == 0) {
        conditional_value = rect.values[0] + rect.values[3];
    } else {
        conditional_value = rect.values[1] - rect.values[2];
    }

    // Step 5: Final computation combining all previous results
    int result = (transformed << 2) + conditional_value - (xor_result % 7);

    return result;
}

