using namespace std;

struct DataPack {
    int values[4];
    string label;
    double coeffs[2];
};

int main() {
    DataPack dp = {{0x1A, 0x2B, 0x3C, 0x4D}, "ComplexCalc", {1.5, 2.7}};
    int mask = 0xF0;
    int shift = 4;
    int temp = 0;
    double accum = 0.0;

    for(int i=0; i<4; i++) {
        int masked = dp.values[i] & mask;
        int shifted = masked >> shift;
        temp ^= shifted;
        if(i%2 == 0) {
            accum += sqrt(dp.coeffs[0] * shifted);
        } else {
            accum -= pow(dp.coeffs[1], shifted/10.0);
        }
    }

    string labelMod = dp.label.substr(0, 5);
    int labelSum = 0;
    for(char c : labelMod) {
        labelSum += static_cast<int>(c);
    }

    bool cond1 = (temp > 10) && (accum < 5.0);
    bool cond2 = !((labelSum % 7) == 0);

    int result = 0;
    if(cond1 || cond2) {
        result = static_cast<int>(abs(accum*temp)) % 100;
    } else {
        result = (temp + static_cast<int>(accum)) & 0xFF;
    }

    return result;
}

import java.util.*;

public class ComplexCalculation {
    public static void main(String[] args) {
        int[][] matrix = {{2, 3, 5}, {7, 11, 13}, {17, 19, 23}};
        List<String> expressions = Arrays.asList("2*3+5", "7+11*13", "17*19+23");
        Map<String, Integer> cache = new HashMap<>();

        int result = 0;
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                String expr = expressions.get(i);
                if (!cache.containsKey(expr)) {
                    int val = evaluateExpression(expr);
                    cache.put(expr, val);
                }
                result += matrix[i][j] * cache.get(expr);
                if (i == j) {
                    result ^= Integer.bitCount(matrix[i][j]);
                }
            }
        }

        result = (int) Math.pow(result, 1.0/3.0) * 1000; // Cube root approximation scaled
        System.out.println(result);
    }

    private static int evaluateExpression(String expr) {
        if (expr.contains("*")) {
            String[] parts = expr.split("\\*");
            int product = 1;
            for (String part : parts) {
                if (part.contains("+")) {
                    String[] addParts = part.split("\\+");
                    int sum = 0;
                    for (String addPart : addParts) {
                        sum += Integer.parseInt(addPart.trim());
                    }
                    product *= sum;
                } else {
                    product *= Integer.parseInt(part.trim());
                }
            }
            return product;
        } else if (expr.contains("+")) {
            String[] parts = expr.split("\\+");
            int sum = 0;
            for (String part : parts) {
                sum += Integer.parseInt(part.trim());
            }
            return sum;
        }
        return Integer.parseInt(expr);
    }
}

#include <stdio.h>
