typedef struct {
    int x;
    int y;
} Point;

typedef struct {
    Point* vertices;
    int count;
} Polygon;

int bitwise_transform(int a, int b) {
    return (a << 2) ^ (b >> 1) & 0xF;
}

int recursive_sum(int n) {
    if (n <= 1) return n;
    return n + recursive_sum(n - 1);
}

int polygon_perimeter(Polygon* p) {
    int perimeter = 0;
    for(int i = 0; i < p->count; i++) {
        int next = (i + 1) % p->count;
        int dx = p->vertices[next].x - p->vertices[i].x;
        int dy = p->vertices[next].y - p->vertices[i].y;
        perimeter += (int)sqrt(dx*dx + dy*dy);
    }
    return perimeter;
}

int main() {
    Point points[] = {{0,0}, {3,0}, {3,4}, {0,4}};
    Polygon rect = {points, 4};

    int a = 15, b = 7;
    int *p1 = &a, *p2 = &b;

    char buffer[20] = "Hello";
    int len = strlen(buffer);

    int result = 0;

    // Complex calculation chain
    result += bitwise_transform(*p1, *p2);
    result *= recursive_sum(len);
    result += polygon_perimeter(&rect);
    result ^= (a & b) | (~a & 0xFF);

    // Pointer manipulation
    *p1 = result >> 2;
    *p2 = result & 0x3;
    result = *p1 + (*p2 << 3);

    // Final adjustment
    result += (int)pow(result % 10, 2);

    return result;
}
